@startuml

class Elevator {
  + currentFloor : int
}

class ElevatorButton {
  + isLit : boolean
}

class FloorButton {
  + direction : string
  + isLit : boolean
}

class Floor {}

Elevator "1" *-- "*" ElevatorButton : has
Floor "1" -- "0..2" FloorButton : has
Elevator "1" -- "*" Floor : travels between

@enduml

